import { Ionicons } from "@expo/vector-icons";
import { useQuery } from "@tanstack/react-query";
import { useRouter } from "expo-router";
import { ActivityIndicator, Pressable, StyleSheet, Text, View } from "react-native";
import { Screen } from "../../ui/Screen";
import { colors, radius, spacing } from "../../ui/tokens";
import { firebaseAuth } from "../auth/firebase";
import { getVendorReturns } from "./vendor.api";

export function VendorReturnsScreen() { const router = useRouter(); const user = firebaseAuth?.currentUser ?? null; const query = useQuery({ queryKey: ["vendor", "returns"], queryFn: () => getVendorReturns(user!), enabled: Boolean(user) }); const open = query.data?.filter((item) => !["REFUNDED", "REJECTED", "CLOSED"].includes(item.status)).length ?? 0; const requested = query.data?.reduce((sum, item) => sum + Number(item.requestedAmount.amountMinor), 0) ?? 0; return <Screen eyebrow="AFTER SALES" title="Customer returns" description="Track return requests, inspection progress and refund exposure for your orders."><View style={styles.metrics}><Metric label="Total returns" value={String(query.data?.length ?? 0)} /><Metric label="Open cases" value={String(open)} /><Metric label="Requested value" value={`৳${(requested / 100).toLocaleString("en-BD")}`} /></View>{query.isLoading ? <ActivityIndicator color={colors.primary} /> : null}<View style={styles.list}>{query.data?.map((item) => <Pressable key={item.id} onPress={() => router.push(`/vendor/returns/${item.id}` as never)} style={styles.card}><View style={styles.header}><Text style={styles.number}>RETURN #{item.id.slice(0, 8).toUpperCase()}</Text><Text style={styles.status}>{item.status.replaceAll("_", " ")}</Text></View><Text style={styles.reason}>{item.reasonCode.replaceAll("_", " ")}</Text><Text style={styles.muted}>{item.reasonDetail || "No additional customer note"}</Text><View style={styles.details}><Cell label="ITEMS" value={String(item.items.reduce((sum, row) => sum + row.quantity, 0))} /><Cell label="REQUESTED" value={`৳${(Number(item.requestedAmount.amountMinor) / 100).toLocaleString("en-BD")}`} /><Cell label="APPROVED" value={item.approvedAmount ? `৳${(Number(item.approvedAmount.amountMinor) / 100).toLocaleString("en-BD")}` : "Pending"} /></View><View style={styles.open}><Text style={styles.openText}>Open return case</Text><Ionicons color={colors.primary} name="arrow-forward" size={16} /></View></Pressable>)}</View>{!query.isLoading && !query.data?.length ? <View style={styles.empty}><Ionicons color={colors.success} name="checkmark-circle-outline" size={52} /><Text style={styles.emptyTitle}>No return requests</Text><Text style={styles.muted}>New customer return cases will appear here automatically.</Text></View> : null}{query.error ? <Text style={styles.error}>{query.error.message}</Text> : null}</Screen>; }
function Metric({ label, value }: { label: string; value: string }) { return <View style={styles.metric}><Text style={styles.metricValue}>{value}</Text><Text style={styles.metricLabel}>{label}</Text></View>; }
function Cell({ label, value }: { label: string; value: string }) { return <View style={styles.cell}><Text style={styles.cellLabel}>{label}</Text><Text style={styles.cellValue}>{value}</Text></View>; }
const styles = StyleSheet.create({ metrics: { flexDirection: "row", flexWrap: "wrap", gap: spacing.md }, metric: { backgroundColor: colors.surface, borderColor: colors.border, borderRadius: radius.lg, borderWidth: 1, flex: 1, minWidth: 190, padding: spacing.md }, metricValue: { color: colors.text, fontSize: 20, fontWeight: "700" }, metricLabel: { color: colors.muted, fontSize: 10 }, list: { gap: spacing.md }, card: { backgroundColor: colors.surface, borderColor: colors.border, borderRadius: radius.lg, borderWidth: 1, gap: spacing.sm, padding: spacing.lg }, header: { alignItems: "center", flexDirection: "row", justifyContent: "space-between" }, number: { color: colors.text, fontWeight: "700" }, status: { backgroundColor: colors.primarySoft, borderRadius: radius.pill, color: colors.primary, fontSize: 8, fontWeight: "700", overflow: "hidden", paddingHorizontal: 9, paddingVertical: 6 }, reason: { color: colors.text, fontSize: 16, fontWeight: "700", textTransform: "capitalize" }, muted: { color: colors.muted, lineHeight: 18 }, details: { flexDirection: "row", flexWrap: "wrap", gap: spacing.sm }, cell: { backgroundColor: "#f8fafc", borderRadius: radius.md, flex: 1, minWidth: 130, padding: spacing.sm }, cellLabel: { color: colors.muted, fontSize: 8, fontWeight: "700" }, cellValue: { color: colors.text, fontWeight: "700", marginTop: 4 }, open: { alignItems: "center", flexDirection: "row", gap: 5, justifyContent: "flex-end" }, openText: { color: colors.primary, fontWeight: "700" }, empty: { alignItems: "center", backgroundColor: colors.surface, borderColor: colors.border, borderRadius: radius.xl, borderStyle: "dashed", borderWidth: 1, gap: spacing.sm, padding: 42 }, emptyTitle: { color: colors.text, fontSize: 19, fontWeight: "700" }, error: { color: colors.danger } });
